import { Tooltip } from '@absoluteui/components/tooltip';
import { Button } from '@absoluteui/components/button';

const save = document.createElement('button');
save.type = 'button';
save.textContent = 'Save';
Button.enhance(save);
document.body.append(save);
Tooltip.create(save, { content: 'Ctrl+S' });

import { Tooltip } from '@absoluteui/components/tooltip';
import { Button } from '@absoluteui/components/button';

const settings = document.createElement('button');
settings.type = 'button';
document.body.append(settings);
// The tooltip names the icon-only button (aria-labelledby), so create it before the Button.
Tooltip.create(settings, { content: 'Settings', relation: 'label', placement: 'bottom' });
Button.enhance(settings, { icon: 'menu', variant: 'ghost' });
